import{f as e,o as s,c as n,a2 as o}from"./chunks/framework.Cd9rfTEn.js";const m=JSON.parse('{"title":"CoopApps — Integraciones","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/integraciones-para-imagenes.md","filePath":"presentacion-stakeholders/integraciones-para-imagenes.md","lastUpdated":null}'),t={name:"presentacion-stakeholders/integraciones-para-imagenes.md"};function r(i,a,l,c,d,p){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="coopapps-—-integraciones" tabindex="-1">CoopApps — Integraciones <a class="header-anchor" href="#coopapps-—-integraciones" aria-label="Permalink to &quot;CoopApps — Integraciones&quot;">​</a></h1><p>Tres imágenes dedicadas a las integraciones con terceros: con quién se conecta el sistema, cómo se conecta, y qué pasa cuando un tercero falla. Todos los datos salen de la especificación; ninguno promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Fuentes</td><td><code>docs/especificacion/anexos/T06-INT-integraciones.md</code> (§1, §2, §5, §9 y fichas §12.4 a §12.18), <code>T08</code> (RNF-NFR-011, RNF-NFR-018, RNF-NFR-041), <code>01-registro-decisiones.md</code> (DEC-003, DEC-074)</td></tr><tr><td>Conteo</td><td>115 fichas de integración (FI-INT), agrupadas en 15 familias. Los conteos por familia salen de las fichas del §12</td></tr><tr><td>Datos</td><td>Todos los nombres de ejemplo son ficticios</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir las imágenes por código: &quot;Generá IMG-IN01&quot;, &quot;Generá IMG-IN02&quot; y &quot;Generá IMG-IN03&quot;.</li><li>Cada imagen trae una <strong>frase para decir</strong> en voz alta mientras se muestra.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar tres diapositivas sobre las integraciones de un sistema para cooperativas de servicios públicos de Argentina con organismos, bancos, redes de cobranza, pasarelas de pago, proveedores de comunicaciones y equipos técnicos. El público mezcla directivos y técnicos.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya hizo el trabajo y lo muestra. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;increíble&quot;, &quot;robusto&quot;, &quot;sin límites&quot;), nada de signos de exclamación, nada de lenguaje publicitario.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras ni integraciones. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina. Los nombres de organismos, bancos y proveedores se escriben tal como figuran en el documento, en texto: no dibujes sus logos.</span></span>
<span class="line"><span>3. Generá cada imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Ámbar #B7791F solo donde el documento lo indique. Sin rojo.</span></span>
<span class="line"><span>5. Composición limpia: mucho espacio en blanco, un título grande (64 a 80 px), un elemento dominante y como máximo cinco elementos de apoyo. Texto mínimo de 20 px (en la grilla de familias se admite 18 px para los ejemplos).</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar), con peso fuerte en títulos y cifras.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de enchufes brillantes, robots ni efectos futuristas.</span></span>
<span class="line"><span>8. Después de cada imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-IN01 a IMG-IN03).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><hr><h2 id="_1-las-tres-ideas" tabindex="-1">1. Las tres ideas <a class="header-anchor" href="#_1-las-tres-ideas" aria-label="Permalink to &quot;1. Las tres ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Título de la imagen</th><th>Idea que deja</th></tr></thead><tbody><tr><td>IMG-IN01</td><td>115 integraciones, cada una con su ficha.</td><td>El sistema ya sabe con quién se tiene que conectar y cómo</td></tr><tr><td>IMG-IN02</td><td>Un solo marco para todas.</td><td>Sumar un banco o una pasarela es configuración, no un cambio en el sistema</td></tr><tr><td>IMG-IN03</td><td>Si un tercero falla, no se duplica nada.</td><td>Ninguna caída externa genera cobros duplicados ni números fiscales salteados</td></tr></tbody></table><hr><h2 id="_2-fichas-y-prompts" tabindex="-1">2. Fichas y prompts <a class="header-anchor" href="#_2-fichas-y-prompts" aria-label="Permalink to &quot;2. Fichas y prompts&quot;">​</a></h2><h3 id="img-in01-—-115-integraciones-cada-una-con-su-ficha" tabindex="-1">IMG-IN01 — 115 integraciones, cada una con su ficha. <a class="header-anchor" href="#img-in01-—-115-integraciones-cada-una-con-su-ficha" aria-label="Permalink to &quot;IMG-IN01 — 115 integraciones, cada una con su ficha.&quot;">​</a></h3><p><strong>Respaldo (T06 §12):</strong> cada integración tiene su ficha: qué intercambia, con qué formato, qué errores devuelve, cómo se concilia y qué hacer si falla. Son 115, en 15 familias:</p><table tabindex="0"><thead><tr><th>Familia</th><th>Fichas</th><th>Ejemplos</th></tr></thead><tbody><tr><td>Fiscal nacional (ARCA)</td><td>17</td><td>Autorización CAE, CAEA y CESP, padrones, Libro IVA Digital, SICORE</td></tr><tr><td>Pasarelas de pago y QR</td><td>13</td><td>Pagos360, Mercado Pago, QR interoperable, DEBIN</td></tr><tr><td>Datos, legado y plataforma</td><td>11</td><td>Migración desde ProCoop, Power BI, contable externo, SFTP</td></tr><tr><td>Reguladores, subsidios y terceros</td><td>10</td><td>ERSeP, ENARGAS, ENACOM, Secretaría de Energía, INAES, RASE</td></tr><tr><td>Redes de cobranza extrabancaria</td><td>9</td><td>Red Link, SIRO, Pago Mis Cuentas, Rapipago, Pago Fácil</td></tr><tr><td>Red, aprovisionamiento y telefonía</td><td>9</td><td>MikroTik, RADIUS, SmartOLT, centrales telefónicas</td></tr><tr><td>Otras de la BASE y de ProCoop</td><td>9</td><td>Imprenta de facturas, monitoreo de red, electrodependientes, catastro</td></tr><tr><td>Fiscal provincial y municipal</td><td>6</td><td>Rentas Córdoba, SIRCAR, ARBA, tasas municipales</td></tr><tr><td>Comunicaciones</td><td>6</td><td>Correo, WhatsApp, SMS, notificaciones push</td></tr><tr><td>Identidad, mapas y geografía</td><td>6</td><td>Google, Ciudadano Digital Córdoba, mapas, Georef</td></tr><tr><td>Medición, telemedición y prepago</td><td>6</td><td>Colectores de lectura, telemedición, medidores prepagos</td></tr><tr><td>Hardware local</td><td>5</td><td>Impresoras, turnero, lectores, balanzas</td></tr><tr><td>Bancos</td><td>3</td><td>Interbanking, extractos bancarios</td></tr><tr><td>Flota, firma e IA</td><td>3</td><td>GPS de flota, firma digital, proveedores de IA</td></tr><tr><td>Débito automático</td><td>2</td><td>Débito en cuenta (CBU) y con tarjetas</td></tr></tbody></table><p><strong>Frase para decir:</strong> &quot;No hay una integración &#39;a ver cómo se hace&#39;. Las 115 tienen su ficha: qué se manda, qué se recibe y qué hacer si falla.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-IN01 con código.</span></span>
<span class="line"><span>Título grande: &quot;115 integraciones, cada una con su ficha.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda, el número &quot;115&quot; enorme en verde con el rótulo &quot;fichas de integración, en 15 familias&quot;. A la derecha, una grilla de 5 × 3 tarjetas, ordenadas de mayor a menor, cada una con el nombre de la familia en negrita, su cifra en verde y dos o tres ejemplos en gris pequeño:</span></span>
<span class="line"><span>&quot;Fiscal nacional (ARCA)&quot; 17 — CAE, CAEA, padrones ·</span></span>
<span class="line"><span>&quot;Pasarelas de pago y QR&quot; 13 — Pagos360, Mercado Pago, QR ·</span></span>
<span class="line"><span>&quot;Datos, legado y plataforma&quot; 11 — ProCoop, Power BI, SFTP ·</span></span>
<span class="line"><span>&quot;Reguladores y subsidios&quot; 10 — ERSeP, ENACOM, INAES ·</span></span>
<span class="line"><span>&quot;Cobranza extrabancaria&quot; 9 — Red Link, Rapipago, Pago Fácil ·</span></span>
<span class="line"><span>&quot;Red y telefonía&quot; 9 — MikroTik, RADIUS, OLT ·</span></span>
<span class="line"><span>&quot;Otras de la BASE y ProCoop&quot; 9 — imprenta, catastro ·</span></span>
<span class="line"><span>&quot;Fiscal provincial y municipal&quot; 6 — Rentas Córdoba, ARBA ·</span></span>
<span class="line"><span>&quot;Comunicaciones&quot; 6 — correo, WhatsApp, SMS ·</span></span>
<span class="line"><span>&quot;Identidad y mapas&quot; 6 — Google, CiDi, Georef ·</span></span>
<span class="line"><span>&quot;Medición y prepago&quot; 6 — telemedición, prepagos ·</span></span>
<span class="line"><span>&quot;Hardware local&quot; 5 — impresoras, turnero ·</span></span>
<span class="line"><span>&quot;Bancos&quot; 3 — Interbanking ·</span></span>
<span class="line"><span>&quot;Flota, firma e IA&quot; 3 — GPS, firma digital ·</span></span>
<span class="line"><span>&quot;Débito automático&quot; 2 — CBU, tarjetas.</span></span>
<span class="line"><span>Sin logos: solo texto.</span></span>
<span class="line"><span>Pie: &quot;Cada ficha dice qué se intercambia, en qué formato, cómo se concilia y qué hacer si falla&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><h3 id="img-in02-—-un-solo-marco-para-todas" tabindex="-1">IMG-IN02 — Un solo marco para todas. <a class="header-anchor" href="#img-in02-—-un-solo-marco-para-todas" aria-label="Permalink to &quot;IMG-IN02 — Un solo marco para todas.&quot;">​</a></h3><p><strong>Respaldo (T06 §1, §2.3 y §5):</strong> todas las integraciones heredan el mismo marco común, resuelto una sola vez:</p><ul><li><strong>Bóveda de credenciales</strong> cifrada por cooperativa, con rotación, vencimientos y registro de cada uso; nadie más que el marco de integraciones lee las claves (DEC-074).</li><li><strong>Certificados digitales</strong> con aviso escalonado antes de que venzan.</li><li><strong>Modo prueba y modo producción</strong> por cooperativa; pasar a producción requiere aprobación.</li><li><strong>Cola con reintentos</strong>, control de duplicados (idempotencia), corte automático cuando el tercero no responde (circuit breaker) y límites de velocidad.</li><li><strong>Bitácora</strong> de cada mensaje enviado y recibido, <strong>sin secretos</strong>.</li><li><strong>Avisos entrantes firmados</strong> (webhooks) que se guardan antes de procesarse y se deduplican.</li><li><strong>Archivos por formatos declarados</strong>, en lugar de las unas 504 clases de código que usa ProCoop para cada formato.</li><li><strong>Conciliación, monitoreo, alertas y contingencia</strong> por conector, con reemplazo manual si hace falta.</li><li><strong>Agente local</strong> para el hardware de la oficina: turnero, impresoras, lectores y balanza.</li></ul><p>Regla de frontera: <strong>un conector nunca escribe los datos de otro módulo</strong>. Entrega un resultado o publica un evento, y el módulo dueño lo aplica con sus propias reglas (DEC-003). Sumar una red de cobranza, una pasarela, un fabricante de medidores o un organismo es <strong>configuración o un adaptador acotado</strong>, nunca un cambio en los módulos de negocio.</p><p><strong>Frase para decir:</strong> &quot;Mañana aparece una pasarela nueva y no hay que tocar la facturación ni la cobranza: se configura un conector y listo.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-IN02 con código.</span></span>
<span class="line"><span>Título grande: &quot;Un solo marco para todas.&quot;</span></span>
<span class="line"><span>Composición en tres franjas verticales:</span></span>
<span class="line"><span>- Izquierda, &quot;Módulos de negocio&quot;: tres bloques grises apilados, &quot;Facturación&quot;, &quot;Cobranza&quot;, &quot;Fiscal&quot;.</span></span>
<span class="line"><span>- Centro, un bloque verde alto, &quot;Marco común de integraciones&quot;, con nueve renglones con ícono de línea: &quot;Bóveda de credenciales&quot; · &quot;Certificados con aviso de vencimiento&quot; · &quot;Modo prueba y producción&quot; · &quot;Cola con reintentos y sin duplicados&quot; · &quot;Corte automático si el tercero no responde&quot; · &quot;Bitácora sin secretos&quot; · &quot;Avisos entrantes firmados&quot; · &quot;Archivos por formatos declarados&quot; · &quot;Conciliación, alertas y contingencia&quot;.</span></span>
<span class="line"><span>- Derecha, &quot;Terceros&quot;: seis tarjetas grises chicas: &quot;ARCA&quot;, &quot;Bancos&quot;, &quot;Redes de cobranza&quot;, &quot;Pasarelas&quot;, &quot;Mensajería&quot;, &quot;Equipos de red&quot;.</span></span>
<span class="line"><span>Entre módulos y marco, flechas con el rótulo &quot;eventos y resultados&quot;; entre marco y terceros, flechas con el rótulo &quot;conectores&quot;.</span></span>
<span class="line"><span>Abajo, una franja gris claro: &quot;Un conector nunca escribe los datos de otro módulo&quot; · &quot;Sumar una pasarela es configuración, no un cambio en el sistema&quot;.</span></span>
<span class="line"><span>Pie: &quot;Formatos de archivo declarados, en lugar de unas 504 clases de código del sistema actual&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="img-in03-—-si-un-tercero-falla-no-se-duplica-nada" tabindex="-1">IMG-IN03 — Si un tercero falla, no se duplica nada. <a class="header-anchor" href="#img-in03-—-si-un-tercero-falla-no-se-duplica-nada" aria-label="Permalink to &quot;IMG-IN03 — Si un tercero falla, no se duplica nada.&quot;">​</a></h3><p><strong>Respaldo (T06 §5.5, §9 y §12; T08):</strong></p><ul><li><strong>Respuesta incierta:</strong> si un tercero no contesta a tiempo, el sistema <strong>consulta el estado antes de reintentar</strong>. Con ARCA, consulta el último comprobante autorizado antes de volver a pedir, así que no hay números salteados ni duplicados.</li><li><strong>Avisos de pago duplicados o desordenados:</strong> en la prueba, 1.000 notificaciones duplicadas y desordenadas producen <strong>un solo cobro confirmado por pago</strong>. El aviso se acusa en 2 segundos o menos y se procesa después.</li><li><strong>ARCA lenta:</strong> si tarda más de 5 segundos durante 15 minutos se alerta y se pasa a la contingencia con CAEA.</li><li><strong>Pasarela caída:</strong> existe un cupón de pago fuera de línea como contingencia.</li><li><strong>Corte automático:</strong> si un tercero falla seguido, se deja de llamarlo por un rato para no saturarlo, y las operaciones quedan en una bandeja de detenidas, sin perderse.</li><li><strong>Pérdida de la cola:</strong> si se pierde el servidor de colas, en 15 minutos o menos se reencola todo desde la base, sin duplicar efectos.</li><li>El objetivo de negocio, escrito en la ficha del marco: ninguna caída externa produce cobros duplicados, numeración fiscal salteada ni socios marcados con error por un problema general.</li></ul><p><strong>Frase para decir:</strong> &quot;Los terceros van a fallar. Lo que no puede pasar es que un socio pague dos veces o que la numeración fiscal quede con huecos. El sistema está hecho para eso.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-IN03 con código.</span></span>
<span class="line"><span>Título grande: &quot;Si un tercero falla, no se duplica nada.&quot;</span></span>
<span class="line"><span>Composición: cuatro filas tipo &quot;situación → respuesta&quot;, cada una con un ícono de línea a la izquierda, la situación en gris y, tras una flecha, la respuesta en negro con tilde verde:</span></span>
<span class="line"><span>1. &quot;El tercero no contesta a tiempo&quot; → &quot;Se consulta el estado antes de reintentar&quot;</span></span>
<span class="line"><span>2. &quot;Llegan avisos de pago duplicados y desordenados&quot; → &quot;Un solo cobro por pago (probado con 1.000 avisos)&quot;</span></span>
<span class="line"><span>3. &quot;ARCA tarda más de 5 s durante 15 min&quot; → &quot;Alerta y contingencia con CAEA&quot;</span></span>
<span class="line"><span>4. &quot;Una pasarela se cae&quot; → &quot;Cupón de pago fuera de línea&quot;</span></span>
<span class="line"><span>La situación de cada fila con borde ámbar suave; la respuesta con borde verde.</span></span>
<span class="line"><span>A la derecha, un sello circular verde grande: &quot;0 cobros duplicados · 0 números salteados&quot;.</span></span>
<span class="line"><span>Pie: &quot;Las operaciones detenidas esperan en una bandeja; nada se pierde&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><hr><h2 id="_3-notas-para-el-presentador" tabindex="-1">3. Notas para el presentador <a class="header-anchor" href="#_3-notas-para-el-presentador" aria-label="Permalink to &quot;3. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Dónde va.</strong> IMG-IN01 abre el bloque técnico o va después de IMG-E08 (&quot;Si ARCA se cae, la cooperativa sigue.&quot;). IMG-IN03 profundiza esa misma imagen; si hay poco tiempo, mostrar solo una de las dos.</li><li><strong>El sello de IMG-IN03 es el objetivo de diseño</strong>, escrito en <code>T06</code> §1 y verificado por pruebas (la de 1.000 avisos duplicados y la de caos con ARCA). No es una medición en producción todavía.</li><li><strong>Las 504 clases</strong> son las de ProCoop para leer y generar archivos de bancos y entes. No nombrar al proveedor del sistema actual en voz alta.</li><li><strong>Algunas fichas dependen de cada cooperativa</strong> (por ejemplo, el organismo provincial o los entes recaudadores que use). La ficha existe; la conexión se habilita por cooperativa.</li></ul>`,32)])])}const b=e(t,[["render",r]]);export{m as __pageData,b as default};
